// @FIGURE_CODE_BEGIN
// Spec (math coords: +z up, +y right, +x forward; world = (x, z, -y)):
// paraboloid z=2-r^2, r in [0,sqrt2] → LatheGeometry, translucent, vertex-color gradient salmon(bottom)→blue(top), DoubleSide
// cone z=r, r in [0,1] → LatheGeometry, opaque blue-gray
// z-axis: dashed Line 0→2 (hidden part), solid Line+cone head 2→2.9 ; y-axis, x-axis solid with heads, length ~2.4
// base rim: front half solid line, back half dashed (split by camera-facing direction)
// orange rod (CylinderGeometry #ff8800) from (0,r,r) to (0,r,2-r^2), reactive to slider
// radial foot line + label 'r' on xy-plane
// intersection ring: TorusGeometry r=1 tube 0.015 at z=1, bright red-orange
// equation arrows: shafts+heads pointing at cone (from left) and paraboloid (from right)
// golden symmetry sweep: transparent sector at z=1 rotating about z, visible only in Cylindrical mode
// labels: (0,0,2), axis letters x,y,z, equation texts — all addLabel

const MW = (x, y, z) => new THREE.Vector3(x, z, -y); // math → world
const mathGroup = new THREE.Group();
mathGroup.rotation.x = -Math.PI / 2;
scene.add(mathGroup);

/* ── lights ── */
scene.add(new THREE.AmbientLight(0xffffff, 0.75));
const dl = new THREE.DirectionalLight(0xffffff, 0.9);
dl.position.set(3, 5, 2);
scene.add(dl);

/* ── paraboloid z = 2 - r^2 ── */
const RSQ2 = Math.sqrt(2);
{
  const prof = [];
  for (let i = 0; i <= 32; i++) {
    const r = (RSQ2 * i) / 32;
    prof.push(new THREE.Vector2(r, 2 - r * r));
  }
  const g = new THREE.LatheGeometry(prof, 64);
  const pos = g.attributes.position;
  const cols = new Float32Array(pos.count * 3);
  const cTop = new THREE.Color(0x7fa8d9), cBot = new THREE.Color(0xe8a48c), tmp = new THREE.Color();
  for (let i = 0; i < pos.count; i++) {
    const t = pos.getY(i) / 2;
    tmp.copy(cBot).lerp(cTop, Math.pow(t, 0.8));
    cols[i * 3] = tmp.r; cols[i * 3 + 1] = tmp.g; cols[i * 3 + 2] = tmp.b;
  }
  g.setAttribute('color', new THREE.BufferAttribute(cols, 3));
  const m = new THREE.MeshPhongMaterial({
    vertexColors: true, transparent: true, opacity: 0.38,
    side: THREE.DoubleSide, depthWrite: false, shininess: 25,
  });
  mathGroup.add(new THREE.Mesh(g, m));
}

/* ── cone z = r ── */
{
  const prof = [];
  for (let i = 0; i <= 20; i++) {
    const r = i / 20;
    prof.push(new THREE.Vector2(r, r));
  }
  const g = new THREE.LatheGeometry(prof, 64);
  const m = new THREE.MeshPhongMaterial({
    color: 0x6a7f9a, transparent: true, opacity: 0.92,
    side: THREE.DoubleSide, shininess: 40,
  });
  mathGroup.add(new THREE.Mesh(g, m));
}

/* ── axes helper ── */
function axisLine(a, b, dashed = false, color = 0x222222) {
  const g = new THREE.BufferGeometry().setFromPoints([a, b]);
  const m = dashed
    ? new THREE.LineDashedMaterial({ color, dashSize: 0.09, gapSize: 0.07 })
    : new THREE.LineBasicMaterial({ color });
  const l = new THREE.Line(g, m);
  if (dashed) l.computeLineDistances();
  mathGroup.add(l);
  return l;
}
function arrowHead(tip, dir, size = 0.09, color = 0x222222) {
  const c = new THREE.Mesh(
    new THREE.ConeGeometry(size * 0.45, size * 2.2, 12),
    new THREE.MeshBasicMaterial({ color })
  );
  c.position.copy(tip).addScaledVector(dir, -size * 1.1);
  c.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
  mathGroup.add(c);
  return c;
}
// z axis: dashed hidden part 0→2, solid 2→2.9 with head
axisLine(new THREE.Vector3(0, 0, 0), new THREE.Vector3(0, 0, 2.02), true);
axisLine(new THREE.Vector3(0, 0, 2.0), new THREE.Vector3(0, 0, 2.85));
arrowHead(new THREE.Vector3(0, 0, 2.95), new THREE.Vector3(0, 0, 1));
// y axis
axisLine(new THREE.Vector3(0, 0, 0), new THREE.Vector3(0, 2.35, 0));
arrowHead(new THREE.Vector3(0, 2.45, 0), new THREE.Vector3(0, 1, 0));
// x axis
axisLine(new THREE.Vector3(0, 0, 0), new THREE.Vector3(2.1, 0, 0));
arrowHead(new THREE.Vector3(2.2, 0, 0), new THREE.Vector3(1, 0, 0));

/* ── base rim: front solid, back dashed (viewer azimuth ~35° in world → facing math dir) ── */
{
  const front = [], back = [];
  // horizontal component of view dir (azimuth 35°): (cos35, 0, sin35) world → math (0.819, -0.574? ) → use math dir (cos35, sin35)=(0.819,0.574)
  const vd = new THREE.Vector2(Math.cos(THREE.MathUtils.degToRad(35)), Math.sin(THREE.MathUtils.degToRad(35)));
  let prevSide = null;
  const N = 128;
  for (let i = 0; i <= N; i++) {
    const th = (i / N) * Math.PI * 2;
    const p = new THREE.Vector3(RSQ2 * Math.cos(th), RSQ2 * Math.sin(th), 0);
    const side = (p.x * vd.x + p.y * vd.y) >= 0;
    if (prevSide !== null && side !== prevSide) { front.push(p); back.push(p); }
    (side ? front : back).push(p);
    prevSide = side;
  }
  const addPts = (pts, dashed) => {
    if (pts.length < 2) return;
    const g = new THREE.BufferGeometry().setFromPoints(pts);
    const m = dashed
      ? new THREE.LineDashedMaterial({ color: 0x555555, dashSize: 0.09, gapSize: 0.07 })
      : new THREE.LineBasicMaterial({ color: 0x4a6a8a });
    const l = new THREE.Line(g, m);
    if (dashed) l.computeLineDistances();
    mathGroup.add(l);
  };
  addPts(front, false);
  addPts(back, true);
}

/* ── intersection ring r=1, z=1 ── */
const ring = new THREE.Mesh(
  new THREE.TorusGeometry(1, 0.014, 10, 80),
  new THREE.MeshBasicMaterial({ color: 0xdd3300 })
);
ring.rotation.x = Math.PI / 2;
ring.position.set(0, 0, 1);
mathGroup.add(ring);

/* ── orange rod + radial foot line (reactive) ── */
const rodMat = new THREE.MeshPhongMaterial({ color: 0xff8800, emissive: 0x552200 });
const rod = new THREE.Mesh(new THREE.CylinderGeometry(0.028, 0.028, 1, 12), rodMat);
mathGroup.add(rod);
const footGeom = new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(), new THREE.Vector3()]);
const footLine = new THREE.Line(footGeom, new THREE.LineBasicMaterial({ color: 0xff8800 }));
mathGroup.add(footLine);

function updateR(r) {
  const zLo = r, zHi = 2 - r * r;
  const len = Math.max(zHi - zLo, 1e-4);
  rod.scale.y = len;
  rod.position.set(0, r, (zLo + zHi) / 2);
  const p = footGeom.attributes.position;
  p.setXYZ(0, 0, 0, 0);
  p.setXYZ(1, 0, r, 0);
  p.needsUpdate = true;
  rLabel.pos.copy(MW(0, r / 2, 0)).add(new THREE.Vector3(0.06, 0.06, -0.14));
}

/* ── equation arrows ── */
function eqArrow(from, to) {
  const dir = to.clone().sub(from).normalize();
  const len = from.distanceTo(to) - 0.16;
  const shaft = new THREE.Mesh(
    new THREE.CylinderGeometry(0.014, 0.014, len, 8),
    new THREE.MeshBasicMaterial({ color: 0x333333 })
  );
  shaft.position.copy(from).addScaledVector(dir, len / 2);
  shaft.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  mathGroup.add(shaft);
  arrowHead(to.clone().addScaledVector(dir, -0.02), dir, 0.07, 0x333333);
}
eqArrow(new THREE.Vector3(-1.7, 0.2, 1.05), new THREE.Vector3(-0.42, 0.42, 0.72)); // to cone
eqArrow(new THREE.Vector3(1.4, 2.3, 1.05), new THREE.Vector3(0.75, 0.75, 0.92));   // to paraboloid

/* ── golden symmetry sweep (Cylindrical mode) ── */
const sweep = new THREE.Mesh(
  new THREE.CircleGeometry(1, 48, 0, 1.4),
  new THREE.MeshBasicMaterial({ color: 0xffc040, transparent: true, opacity: 0, side: THREE.DoubleSide, depthWrite: false })
);
sweep.rotation.x = -Math.PI / 2; // in math group, z-up: circle default lies in xy-plane already... keep flat at z=1
sweep.position.set(0, 0, 1);
mathGroup.add(sweep);
let sweepTarget = 0;
const sweepRing = new THREE.Mesh(
  new THREE.RingGeometry(0.96, 1.04, 64),
  new THREE.MeshBasicMaterial({ color: 0xffc040, transparent: true, opacity: 0, side: THREE.DoubleSide, depthWrite: false })
);
sweepRing.position.set(0, 0, 1.005);
mathGroup.add(sweepRing);

/* ── camera ── */
setCameraView({ projection: 'perspective', azimuthDeg: 35, elevationDeg: 22, rollDeg: 0, heightFraction: 0.7 });

/* ── labels ── */
addLabel('(0, 0, 2)', MW(0, 0, 2.12), { offset: [44, -8], fontSize: '14px' });
addLabel('<b>z</b>', MW(0, 0, 3.05), { fontSize: '15px' });
addLabel('<b>y</b>', MW(0, 2.62, 0), { fontSize: '15px' });
addLabel('<b>x</b>', MW(2.38, 0, 0), { fontSize: '15px', offset: [0, 10] });
const rLabel = addLabel('r', MW(0, 0.15, 0), { color: '#cc6600', bold: true });
const coneLbl = addLabel('z = &radic;(x<sup>2</sup> + y<sup>2</sup>)', MW(-1.85, 0.15, 1.1), { fontSize: '14px', offset: [-40, 0] });
const parLbl = addLabel('z = 2 &minus; x<sup>2</sup> &minus; y<sup>2</sup>', MW(1.55, 2.45, 1.1), { fontSize: '14px', offset: [55, 0] });

/* ── controls ── */
const slider = document.getElementById('radiusR');
const rVal = document.getElementById('rVal');
slider.addEventListener('input', () => {
  const r = parseFloat(slider.value);
  rVal.textContent = r.toFixed(2);
  updateR(r);
});

const sel = document.getElementById('coordSystem');
function applyCoord(mode) {
  if (mode === 'Cylindrical') {
    coneLbl.div.innerHTML = 'z = r';
    parLbl.div.innerHTML = 'z = 2 &minus; r<sup>2</sup>';
    sweepTarget = 1;
  } else {
    coneLbl.div.innerHTML = 'z = &radic;(x<sup>2</sup> + y<sup>2</sup>)';
    parLbl.div.innerHTML = 'z = 2 &minus; x<sup>2</sup> &minus; y<sup>2</sup>';
    sweepTarget = 0;
  }
}
sel.addEventListener('change', () => applyCoord(sel.value));

/* ── demo steps ── */
const steps = [
  {
    title: 'A radial segment near the axis',
    narration: 'At r = 0.3 the vertical segment runs from the cone surface at z = r = 0.3 up to the paraboloid at z = 2 − r² = 1.91 — one thin column of the solid whose volume we will integrate.',
    state: { radiusR: 0.3, coordSystem: 'Cartesian' },
  },
  {
    title: 'Approach the intersection',
    narration: 'Increase r toward 1: the segment gets shorter as the two surfaces converge. At r = 1 the segment vanishes because z = r and z = 2 − r² coincide — the surfaces meet on the circle r = 1, z = 1, giving the outer limit of the radial integral.',
    state: { radiusR: 0.95, coordSystem: 'Cartesian' },
  },
  {
    title: 'Why cylindrical?',
    narration: 'Switch to cylindrical labels: the equations become z = r and z = 2 − r² with no angular dependence at all. The highlighted circular symmetry shows the whole solid is described by 0 ≤ θ ≤ 2π, 0 ≤ r ≤ 1, r ≤ z ≤ 2 − r².',
    state: { radiusR: 0.6, coordSystem: 'Cylindrical' },
  },
];
let stepIdx = -1;
function goToStep(i) {
  stepIdx = ((i % steps.length) + steps.length) % steps.length;
  const s = steps[stepIdx];
  slider.value = s.state.radiusR;
  slider.dispatchEvent(new Event('input'));
  sel.value = s.state.coordSystem;
  applyCoord(s.state.coordSystem);
  document.getElementById('stepTitle').textContent = (stepIdx + 1) + '. ' + s.title;
  document.getElementById('stepText').textContent = s.narration;
}
document.getElementById('btnNext').addEventListener('click', () => goToStep(stepIdx + 1));
document.getElementById('btnPrev').addEventListener('click', () => goToStep(stepIdx - 1));

/* ── sweep animation ── */
const _origAnimate = null;
(function addSweep() {
  const base = performance.now();
  function tick() {
    requestAnimationFrame(tick);
