const MW = (x, y, z) => new THREE.Vector3(x, z, -y); // math → world
const mathGroup = new THREE.Group();
mathGroup.rotation.x = -Math.PI / 2;
scene.add(mathGroup);

/* ── lights ── */
scene.add(new THREE.AmbientLight(0xffffff, 0.7));
const dl = new THREE.DirectionalLight(0xffffff, 0.9);
dl.position.set(3, 5, 2);
scene.add(dl);

/* ── paraboloid z = 2 - r^2 : saturated salmon→blue gradient ── */
const RSQ2 = Math.sqrt(2);
{
  const prof = [];
  for (let i = 0; i <= 32; i++) {
    const r = (RSQ2 * i) / 32;
    prof.push(new THREE.Vector2(r, 2 - r * r));
  }
  const g = new THREE.LatheGeometry(prof, 64);
  const pos = g.attributes.position;
  const cols = new Float32Array(pos.count * 3);
  const cTop = new THREE.Color(0x5b8fd6), cBot = new THREE.Color(0xe89070), tmp = new THREE.Color();
  for (let i = 0; i < pos.count; i++) {
    const t = pos.getY(i) / 2;
    tmp.copy(cBot).lerp(cTop, Math.pow(t, 0.85));
    cols[i * 3] = tmp.r; cols[i * 3 + 1] = tmp.g; cols[i * 3 + 2] = tmp.b;
  }
  g.setAttribute('color', new THREE.BufferAttribute(cols, 3));
  const m = new THREE.MeshPhongMaterial({
    vertexColors: true, transparent: true, opacity: 0.45,
    side: THREE.DoubleSide, depthWrite: false, shininess: 30,
  });
  mathGroup.add(new THREE.Mesh(g, m));
}

/* ── cone z = r : translucent enough to reveal the dashed z-axis ── */
{
  const prof = [];
  for (let i = 0; i <= 20; i++) {
    const r = i / 20;
    prof.push(new THREE.Vector2(r, r));
  }
  const g = new THREE.LatheGeometry(prof, 64);
  const m = new THREE.MeshPhongMaterial({
    color: 0x6a7f9a, transparent: true, opacity: 0.55,
    side: THREE.DoubleSide, depthWrite: false, shininess: 40,
  });
  mathGroup.add(new THREE.Mesh(g, m));
}

/* ── axes helpers ── */
function axisLine(a, b, dashed = false, color = 0x222222) {
  const g = new THREE.BufferGeometry().setFromPoints([a, b]);
  const m = dashed
    ? new THREE.LineDashedMaterial({ color, dashSize: 0.09, gapSize: 0.07 })
    : new THREE.LineBasicMaterial({ color });
  const l = new THREE.Line(g, m);
  if (dashed) l.computeLineDistances();
  mathGroup.add(l);
  return l;
}
function arrowHead(tip, dir, size = 0.09, color = 0x222222) {
  const c = new THREE.Mesh(
    new THREE.ConeGeometry(size * 0.45, size * 2.2, 12),
    new THREE.MeshBasicMaterial({ color })
  );
  c.position.copy(tip).addScaledVector(dir, -size * 1.1);
  c.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
  mathGroup.add(c);
  return c;
}
// z axis: dashed hidden part 0→2, solid 2→2.85 with head
axisLine(new THREE.Vector3(0, 0, 0), new THREE.Vector3(0, 0, 2.02), true);
axisLine(new THREE.Vector3(0, 0, 2.0), new THREE.Vector3(0, 0, 2.85));
arrowHead(new THREE.Vector3(0, 0, 2.95), new THREE.Vector3(0, 0, 1));
// y axis
axisLine(new THREE.Vector3(0, 0, 0), new THREE.Vector3(0, 2.35, 0));
arrowHead(new THREE.Vector3(0, 2.45, 0), new THREE.Vector3(0, 1, 0));
// x axis
axisLine(new THREE.Vector3(0, 0, 0), new THREE.Vector3(2.1, 0, 0));
arrowHead(new THREE.Vector3(2.2, 0, 0), new THREE.Vector3(1, 0, 0));

/* ── base rim: front solid, back dashed ── */
{
  const front = [], back = [];
  const vd = new THREE.Vector2(Math.cos(THREE.MathUtils.degToRad(35)), Math.sin(THREE.MathUtils.degToRad(35)));
  let prevSide = null;
  const N = 128;
  for (let i = 0; i <= N; i++) {
    const th = (i / N) * Math.PI * 2;
    const p = new THREE.Vector3(RSQ2 * Math.cos(th), RSQ2 * Math.sin(th), 0);
    const side = (p.x * vd.x + p.y * vd.y) >= 0;
    if (prevSide !== null && side !== prevSide) { front.push(p); back.push(p); }
    (side ? front : back).push(p);
    prevSide = side;
  }
  const addPts = (pts, dashed) => {
    if (pts.length < 2) return;
    const g = new THREE.BufferGeometry().setFromPoints(pts);
    const m = dashed
      ? new THREE.LineDashedMaterial({ color: 0x555555, dashSize: 0.09, gapSize: 0.07 })
      : new THREE.LineBasicMaterial({ color: 0x4a6a8a });
    const l = new THREE.Line(g, m);
    if (dashed) l.computeLineDistances();
    mathGroup.add(l);
  };
  addPts(front, false);
  addPts(back, true);
}

/* ── intersection ring r=1, z=1 : thin subtle line, off by default ── */
const ringPts = [];
for (let i = 0; i <= 96; i++) {
  const th = (i / 96) * Math.PI * 2;
  ringPts.push(new THREE.Vector3(Math.cos(th), Math.sin(th), 1));
}
const ring = new THREE.Line(
  new THREE.BufferGeometry().setFromPoints(ringPts),
  new THREE.LineBasicMaterial({ color: 0x992222, transparent: true, opacity: 0.85 })
);
ring.visible = false;
mathGroup.add(ring);
document.getElementById('showRing').addEventListener('change', (e) => {
  ring.visible = e.target.checked;
});

/* ── thin orange rod + radial foot line (reactive) ── */
const rod = new THREE.Mesh(
  new THREE.CylinderGeometry(0.016, 0.016, 1, 10),
  new THREE.MeshPhongMaterial({ color: 0xff8800, transparent: true, opacity: 0.9 })
);
mathGroup.add(rod);
const footGeom = new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(), new THREE.Vector3()]);
const footLine = new THREE.Line(footGeom, new THREE.LineBasicMaterial({ color: 0xcc7722 }));
mathGroup.add(footLine);
// small marker dots at rod ends
const dotLo = new THREE.Mesh(new THREE.SphereGeometry(0.03, 10, 10), new THREE.MeshBasicMaterial({ color: 0xcc7722 }));
const dotHi = dotLo.clone();
mathGroup.add(dotLo); mathGroup.add(dotHi);

function updateR(r) {
  const zLo = r, zHi = 2 - r * r;
  const len = Math.max(zHi - zLo, 1e-4);
  rod.scale.y = len;
  rod.position.set(0, r, (zLo + zHi) / 2);
  dotLo.position.set(0, r, zLo);
  dotHi.position.set(0, r, zHi);
  const p = footGeom.attributes.position;
  p.setXYZ(0, 0, 0, 0);
  p.setXYZ(1, 0, r, 0);
  p.needsUpdate = true;
  rLabel.pos.copy(MW(0, r / 2, 0)).add(new THREE.Vector3(0.06, 0.06, -0.14));
}

/* ── equation arrows ── */
function eqArrow(from, to) {
  const dir = to.clone().sub(from).normalize();
  const len = from.distanceTo(to) - 0.16;
  const shaft = new THREE.Mesh(
    new THREE.CylinderGeometry(0.014, 0.014, len, 8),
    new THREE.MeshBasicMaterial({ color: 0x333333 })
  );
  shaft.position.copy(from).addScaledVector(dir, len / 2);
  shaft.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  mathGroup.add(shaft);
  arrowHead(to.clone().addScaledVector(dir, -0.02), dir, 0.07, 0x333333);
}
