// @FIGURE_CODE_BEGIN
// World mapping: math (x,y,z) → world (y, z, x)  — math z is world up, math y
// points screen-right, math x points toward the viewer (lower-left). No rotated
// group: LatheGeometry is built directly about the world Y axis.
//
// Spec:
// paraboloid z=2-r^2, r in [0,sqrt2] → LatheGeometry(64 radial seg), translucent
//   (op 0.38), vertex-color gradient salmon #e8a48c (rim) → blue #7fa8d9 (apex), DoubleSide
// cone z=r, r in [0,1] → LatheGeometry, darker slate blue #4e6484, opacity 0.72 (clearly distinct)
// z-axis: dashed Line 0→2 (drawn on top via depthTest:false), solid 2→2.85 + cone head
// y-axis right, x-axis toward viewer, solid with heads
// base rim ellipse at z=0: front half solid, back half dashed (split by view azimuth 35°)
// orange rod #ff8800, THIN (r=0.016), from (0,r,r) to (0,r,2-r^2) along math +y, slider-reactive
// radial foot line + label 'r' on xy-plane
// intersection ring: thin Line circle (radius 1 at z=1), dark red, hidden unless checkbox on
// equation arrows: shafts+heads pointing at cone (from left) and paraboloid (from right)
// golden symmetry sweep: transparent sector at z=1 rotating about z, Cylindrical mode only
// labels: (0,0,2), x,y,z, equation texts — all addLabel

const MW = (x, y, z) => new THREE.Vector3(y, z, x); // math → world

/* ── lights ── */
scene.add(new THREE.AmbientLight(0xffffff, 0.75));
const dl = new THREE.DirectionalLight(0xffffff, 0.85);
dl.position.set(3, 5, 2);
scene.add(dl);

/* ── paraboloid z = 2 - r^2 : salmon→blue gradient, translucent ── */
const RSQ2 = Math.sqrt(2);
{
  const prof = [];
  for (let i = 0; i <= 32; i++) {
    const r = (RSQ2 * i) / 32;
    prof.push(new THREE.Vector2(r, 2 - r * r));
  }
  const g = new THREE.LatheGeometry(prof, 64);
  const pos = g.attributes.position;
  const cols = new Float32Array(pos.count * 3);
  const cTop = new THREE.Color(0x7fa8d9), cBot = new THREE.Color(0xe8a48c), tmp = new THREE.Color();
  for (let i = 0; i < pos.count; i++) {
    const t = pos.getY(i) / 2;
    tmp.copy(cBot).lerp(cTop, Math.pow(t, 0.85));
    cols[i * 3] = tmp.r; cols[i * 3 + 1] = tmp.g; cols[i * 3 + 2] = tmp.b;
  }
  g.setAttribute('color', new THREE.BufferAttribute(cols, 3));
  const m = new THREE.MeshPhongMaterial({
    vertexColors: true, transparent: true, opacity: 0.38,
    side: THREE.DoubleSide, depthWrite: false, shininess: 25,
  });
  const mesh = new THREE.Mesh(g, m);
  mesh.renderOrder = 1;
  scene.add(mesh);
}

/* ── cone z = r : darker, more opaque slate blue so it reads as interior ── */
{
  const prof = [];
  for (let i = 0; i <= 20; i++) {
    const r = i / 20;
    prof.push(new THREE.Vector2(r, r));
  }
  const g = new THREE.LatheGeometry(prof, 64);
  const m = new THREE.MeshPhongMaterial({
    color: 0x4e6484, transparent: true, opacity: 0.72,
    side: THREE.DoubleSide, depthWrite: false, shininess: 35,
  });
  const mesh = new THREE.Mesh(g, m);
  mesh.renderOrder = 2;
  scene.add(mesh);
}

/* ── axis helpers ── */
function axisLine(a, b, dashed = false, color = 0x222222, onTop = false) {
  const g = new THREE.BufferGeometry().setFromPoints([a, b]);
  const m = dashed
    ? new THREE.LineDashedMaterial({ color, dashSize: 0.1, gapSize: 0.07, depthTest: !onTop })
    : new THREE.LineBasicMaterial({ color });
  const l = new THREE.Line(g, m);
  if (dashed) l.computeLineDistances();
  if (onTop) l.renderOrder = 20;
  scene.add(l);
  return l;
}
function arrowHead(tip, dir, size = 0.09, color = 0x222222) {
  const c = new THREE.Mesh(
    new THREE.ConeGeometry(size * 0.45, size * 2.2, 12),
    new THREE.MeshBasicMaterial({ color })
  );
  c.position.copy(tip).addScaledVector(dir, -size * 1.1);
  c.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
  scene.add(c);
  return c;
}
// z axis: dashed hidden part 0→2 (drawn on top of translucent shells), solid 2→2.85 + head
axisLine(MW(0, 0, 0), MW(0, 0, 2.02), true, 0x333333, true);
axisLine(MW(0, 0, 2.0), MW(0, 0, 2.85));
arrowHead(MW(0, 0, 2.95), MW(0, 0, 1));
// y axis (screen right)
axisLine(MW(0, 0, 0), MW(0, 2.35, 0));
arrowHead(MW(0, 2.45, 0), MW(0, 1, 0));
// x axis (toward viewer, lower-left)
axisLine(MW(0, 0, 0), MW(2.1, 0, 0));
arrowHead(MW(0, 2.2, 0), MW(1, 0, 0));

/* ── base rim at z=0: front half solid, back half dashed ── */
{
  const az = THREE.MathUtils.degToRad(35);          // camera azimuth
  const vd = new THREE.Vector2(Math.cos(az), Math.sin(az)); // view dir in world (x,z) = math (y,x)
  const front = [], back = [];
  let prevSide = null;
  const N = 160;
  for (let i = 0; i <= N; i++) {
    const th = (i / N) * Math.PI * 2;
    const mx = RSQ2 * Math.cos(th), my = RSQ2 * Math.sin(th); // math coords
    const w = MW(mx, my, 0);
    const side = (w.x * vd.x + w.z * vd.y) >= 0;
    if (prevSide !== null && side !== prevSide) { front.push(w); back.push(w); }
    (side ? front : back).push(w);
    prevSide = side;
  }
  const addPts = (pts, dashed) => {
    if (pts.length < 2) return;
    const g = new THREE.BufferGeometry().setFromPoints(pts);
    const m = dashed
      ? new THREE.LineDashedMaterial({ color: 0x666666, dashSize: 0.09, gapSize: 0.07 })
      : new THREE.LineBasicMaterial({ color: 0x4a6a8a });
    const l = new THREE.Line(g, m);
    if (dashed) l.computeLineDistances();
    scene.add(l);
  };
  addPts(front, false);
  addPts(back, true);
}

/* ── intersection ring r=1, z=1 : thin line, off by default ── */
const ringPts = [];
for (let i = 0; i <= 96; i++) {
  const th = (i / 96) * Math.PI * 2;
  ringPts.push(MW(Math.cos(th), Math.sin(th), 1));
}
const ring = new THREE.Line(
  new THREE.BufferGeometry().setFromPoints(ringPts),
  new THREE.LineBasicMaterial({ color: 0x992222, transparent: true, opacity: 0.9 })
);
ring.visible = false;
ring.renderOrder = 5;
scene.add(ring);
document.getElementById('showRing').addEventListener('change', (e) => {
  ring.visible = e.target.checked;
});

/* ── thin orange rod + radial foot line (reactive), placed along math +y ── */
const rod = new THREE.Mesh(
  new THREE.CylinderGeometry(0.016, 0.016, 1, 10),
  new THREE.MeshPhongMaterial({ color: 0xff8800, transparent: true, opacity: 0.95 })
);
rod.renderOrder = 6;
scene.add(rod);
const footGeom = new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(), new THREE.Vector3()]);
const footLine = new THREE.Line(footGeom, new THREE.LineBasicMaterial({ color: 0xcc7722 }));
scene.add(footLine);
const dotMat = new THREE.MeshBasicMaterial({ color: 0xcc7722 });
const dotLo = new THREE.Mesh(new THREE.SphereGeometry(0.035, 10, 10), dotMat);
const dotHi = new THREE.Mesh(new THREE.SphereGeometry(0.035, 10, 10), dotMat);
dotLo.renderOrder = 6; dotHi.renderOrder = 6;
scene.add(dotLo); scene.add(dotHi);

function updateR(r) {
  const zLo = r, zHi = 2 - r * r;
  const len = Math.max(zHi - zLo, 1e-4);
  rod.scale.y = len;
  rod.position.copy(MW(0, r, (zLo + zHi) / 2));
  dotLo.position.copy(MW(0, r, zLo));
  dotHi.position.copy(MW(0, r, zHi));
  const p = footGeom.attributes.position;
  p.setXYZ(0, 0, 0, 0);
  const f = MW(0, r, 0);
  p.setXYZ(1, f.x, f.y, f.z);
  p.needsUpdate = true;
  rLabel.pos.copy(MW(0, r / 2, 0)).add(new THREE.Vector3(0.1, 0.07, 0.1));
}

/* ── equation arrows (dark shafts + heads) ── */
function eqArrow(fromMath, toMath) {
  const from = MW(...fromMath), to = MW(...toMath);
  const dir = to.clone().sub(from).normalize();
  const len = from.distanceTo(to) - 0.16;
  const shaft = new THREE.Mesh(
    new THREE.CylinderGeometry(0.014, 0.014, len, 8),
    new THREE.MeshBasicMaterial({ color: 0x333333 })
  );
  shaft.position.copy(from).addScaledVector(dir, len / 2);
  shaft.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  scene.add(shaft);
  arrowHead(to.clone().addScaledVector(dir, -0.02), dir, 0.07, 0x333333);
}
eqArrow([-1.75, 0.3, 0.95], [-0.5, 0.5, 0.68]);  // from left to cone
eqArrow([0.7, 2.6, 0.85], [0.6, 0.85, 0.95]);    // from right to paraboloid

/* ── golden symmetry sweep (Cylindrical mode) ── */
const sweep = new THREE.Mesh(
  new THREE.CircleGeometry(1, 48, 0, 1.4),
  new THREE.MeshBasicMaterial({ color: 0xffc040, transparent: true, opacity: 0, side: THREE.DoubleSide, depthWrite: false })
);
sweep.rotation.x = -Math.PI / 2;   // lie flat in xy-plane
sweep.position.y = 1;              // at z = 1
sweep.renderOrder = 4;
scene.add(sweep);
let sweepTarget = 0;

/* ── camera: wider, more elevated so the dome reads as a squat dome ── */
setCameraView({ projection: 'perspective', azimuthDeg: 35, elevationDeg: 30, rollDeg: 0, heightFraction: 0.72 });

/* ── labels ── */
addLabel('(0, 0, 2)', MW(0, 0, 2.14), { offset: [48, -10], fontSize: '14px' });
addLabel('<b>z</b>', MW(0, 0, 3.08), { fontSize: '15px' });
addLabel('<b>y</b>', MW(0, 2.62, 0), { fontSize: '15px' });
addLabel('<b>x</b>', MW(2.4, 0, 0), { fontSize: '15px', offset: [0, 12] });
const rLabel = addLabel('r', MW(0, 0.15, 0), { color: '#cc6600', bold: true });
const coneLbl = addLabel('z = &radic;(x<sup>2</sup> + y<sup>2</sup>)', MW(-1.9, 0.25, 1.0), { fontSize: '14px', offset: [-45, 0] });
const parLbl = addLabel('z = 2 &minus; x<sup>2</sup> &minus; y<sup>2</sup>', MW(0.75, 2.75, 0.9), { fontSize: '14px', offset: [60, 0] });

/* ── controls ── */
const slider = document.getElementById('radiusR');
const rVal = document.getElementById('rVal');
slider.addEventListener('input', () => {
  const r = parseFloat(slider.value);
  rVal.textContent = r.toFixed(2);
  updateR(r);
});

const sel = document.getElementById('coordSystem');
function applyCoord(mode) {
  if (mode === 'Cylindrical') {
    coneLbl.div.innerHTML = 'z = r';
    parLbl.div.innerHTML = 'z = 2 &minus; r<sup>2</sup>';
    sweepTarget = 1;
  } else {
    coneLbl.div.innerHTML = 'z = &radic;(x<sup>2</sup> + y<sup>2</sup>)';
    parLbl.div.innerHTML = 'z = 2 &minus; x<sup>2</sup> &minus; y<sup>2</sup>';
    sweepTarget = 0;
  }
}
sel.addEventListener('change', () => applyCoord(sel.value));

/* ── demo steps ── */
const steps = [
  {
    title: 'A radial segment near the axis',
    narration: 'At r = 0.3 the vertical segment runs from the cone surface at z = r = 0.3 up to the paraboloid at z = 2 − r² = 1.91 — one thin column of the solid whose volume we will integrate.',
    state: { radiusR: 0.3, coordSystem: 'Cartesian' },
  },
  {
    title: 'Approach the intersection',
    narration: 'Increase r toward 1: the segment gets shorter as the two surfaces converge. At r = 1 the segment vanishes because z = r and z = 2 − r² coincide — the surfaces meet on the circle r = 1, z = 1, giving the outer limit of the radial integral. Tick "Intersection ring" to highlight that circle.',
    state: { radiusR: 0.95, coordSystem: 'Cartesian' },
  },
  {
    title: 'Why cylindrical?',
    narration: 'Switch to cylindrical labels: the equations become z = r and z = 2 − r² with no angular dependence at all. The highlighted circular symmetry shows the whole solid is described by 0 ≤ θ ≤ 2π, 0 ≤ r ≤ 1, r ≤ z ≤ 2 − r².',
    state: { radiusR: 0.6, coordSystem: 'Cylindrical' },
  },
];
let stepIdx = -1;
function goToStep(i) {
  stepIdx = ((i % steps.length) + steps.length) % steps.length;
  const s = steps[stepIdx];
  slider.value = s.state.radiusR;
  slider.dispatchEvent(new Event('input'));
  sel.value = s.state.coordSystem;
  applyCoord(s.state.coordSystem);
  document.getElementById('stepTitle').textContent = (stepIdx + 1) + '. ' + s.title;
  document.getElementById('stepText').textContent = s.narration;
}
document.getElementById('btnNext').addEventListener('click', () => goToStep(stepIdx + 1));
document.getElementById('btnPrev').addEventListener('click', () => goToStep(stepIdx - 1));

/* ── sweep animation ── */
(function addSweep() {
  const base = performance.now();
  function tick() {
    requestAnimationFrame(tick);
    const t = (performance.now() - base) / 1000;
    const cur = sweep.material.opacity;
    const next = cur + (sweepTarget * 0.35 - cur) * 0.08;
    sweep.material.opacity = next;
    if (next > 0.005) sweep.rotation.z = t * 0.9;
  }
  tick();
})();

updateR(0.3);
applyCoord('Cartesian');
